package com.retailops.orders.pricing;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigDecimal;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvFileSource;

import com.retailops.schemas.CustomerTier;
import com.retailops.schemas.Region;

/** Region x units x net-amount matrix generated by {@code scripts/generate_pricing_cases.py}. */
class GeneratedShippingMatrixTest {

    private final ShippingPolicy policy = new ShippingPolicy(PricingProperties.defaults());

    @ParameterizedTest(name = "{0} {1} units={2} net={3} -> {4}")
    @CsvFileSource(resources = "/generated/shipping-matrix.csv", numLinesToSkip = 1)
    void shippingCost(Region region, CustomerTier tier, int units, String net, String expected) {
        assertThat(policy.cost(new BigDecimal(net), units, region, tier, false)).isEqualTo(new BigDecimal(expected));
    }
}
